131	int do_mkdir(char* dirname)
132	{
133	    /* Search Parent Dir */
134	    enable_sum();
135	
136	    int dirname_pos = 0;
137	    dir_t* cur_dir;
138	    uint16_t lastdir_inode;
139	    uint32_t lastdir_block;
140	
141	    // search from root dir / current dir?
142	    if(dirname[dirname_pos] == '/'){
143	        read_superblock();
144	        read_block(superblock->root_block_id);
145	        cur_dir = cached_block_base;
146	        lastdir_inode = superblock->root_inode_id;
147	        lastdir_block = superblock->root_block_id;
148	        dirname_pos++;    
149	    }
150	    else{
151	        read_block(current_dir_block);
152	        cur_dir = cached_block_base;
153	        lastdir_inode = current_dir_inode;
154	        lastdir_block = current_dir_block;
155	    }
156	
157	    char nextdirname[29];
158	    while(1){
159	        // Get name of next dir
160	        int nextdirname_pos = 0;
161	        while(dirname[dirname_pos] != '/' && dirname[dirname_pos] != '\0'){
162	            nextdirname[nextdirname_pos++] = dirname[dirname_pos++];
163	        }
164	        nextdirname[nextdirname_pos] = '\0';
165	
166	        // Last?
167	        if(dirname[dirname_pos] == '\0' || 
168	           (dirname[dirname_pos + 1] == '\0' && dirname[dirname_pos] == '/')){
169	            break;
170	        }
171	
172	        // Search
173	        int i = 0;
174	        uint16_t nextdir_inode_id;
175	        uint32_t nextdir_block_id;
176	        for(i = 0; i < 128; i++){
177	            if(cur_dir->entry[i].type == DIR && !strcmp(cur_dir->entry[i].name, nextdirname)){
178	                nextdir_inode_id = cur_dir->entry[i].inode;
179	                inode_t* nextdir_inode = read_inode(nextdir_inode_id);
180	                nextdir_block_id = nextdir_inode->direct_blocks[0];
181	                lastdir_inode = nextdir_inode_id;
182	                lastdir_block = nextdir_block_id;
183	                break;
184	            }
185	        }
186	        if(i == 128){
187	            disable_sum();
188	            return 0;
189	        }
190	
191	        dirname_pos++;
192	        read_block(nextdir_block_id);
193	        cur_dir = cached_block_base;
194	    }
195	
196	    disable_sum();
197	    /* Search Parent Dir End */
198	
199	    read_block(lastdir_block);
200	    cur_dir = cached_block_base;
201	    for(int i = 0; i < 128; i++){
202	        if(cur_dir->entry[i].type == DIR && !strcmp(cur_dir->entry[i].name, nextdirname)){
203	            return 0;
204	        }
205	    }
206	
207	    for(int i = 0; i < 128; i++){
208	        if(cur_dir->entry[i].type == EMPTY){
209	            uint16_t inode_id = alloc_inode();
210	            uint32_t block_id = alloc_block();
211	
212	            // Modify Current Dir
213	            inode_t* parent_inode = read_inode(lastdir_inode);
214	            parent_inode->link = parent_inode->link + 1;
215	            write_inode(lastdir_inode);
216	
217	            cur_dir->entry[i].type = DIR;
218	            strcpy(cur_dir->entry[i].name, nextdirname);
219	            cur_dir->entry[i].inode = inode_id;
220	            write_block(lastdir_block);
221	
222	            // Modify New Inode
223	            inode_t* new_inode = read_inode(inode_id);
224	            new_inode->mode = 0;
225	            new_inode->owner = current_running[cpu_id]->pid;
226	            new_inode->size = 4096;
227	            new_inode->direct_blocks[0] = block_id;
228	            new_inode->link = 2;
229	            write_inode(inode_id);
230	            
231	            //Modify New Dir
232	            read_block(block_id);
233	            memset(cached_block_base, 0, 4096);
234	            dir_t* new_dir = cached_block_base;
235	            new_dir->entry[0].type = DIR;
236	            strcpy(new_dir->entry[0].name, ".");
237	            new_dir->entry[0].inode = inode_id;
238	            new_dir->entry[1].type = DIR;
239	            strcpy(new_dir->entry[1].name, "..");
240	            new_dir->entry[1].inode = lastdir_inode;
241	            write_block(block_id);
242	
243	            return 1;
244	        }
245	    }
246	
247	    return 0;
248	}
