36	uintptr_t read_inode(uint16_t inode_id)
37	{
38	    uint64_t sd_block_id = INODE_BEGIN_ID + inode_id / 8;
39	    sbi_sd_read(kva2pa(INODE_CACHE), 1, sd_block_id);
40	    cached_inode_id = inode_id;
41	    uintptr_t ret = INODE_CACHE + 64 * (inode_id % 8);
42	    return ret;
43	}
