10	int do_touch(char* filename)
11	{
12	    /* Search Parent Dir */
13	    enable_sum();
14	
15	    int filename_pos = 0;
16	    dir_t* cur_dir;
17	    uint16_t lastdir_inode;
18	    uint32_t lastdir_block;
19	
20	    // search from root dir / current dir?
21	    if(filename[filename_pos] == '/'){
22	        read_superblock();
23	        read_block(superblock->root_block_id);
24	        cur_dir = cached_block_base;
25	        lastdir_inode = superblock->root_inode_id;
26	        lastdir_block = superblock->root_block_id;
27	        filename_pos++;    
28	    }
29	    else{
30	        read_block(current_dir_block);
31	        cur_dir = cached_block_base;
32	        lastdir_inode = current_dir_inode;
33	        lastdir_block = current_dir_block;
34	    }
35	
36	    char nextdirname[29];
37	    while(1){
38	        // Get name of next dir
39	        int nextdirname_pos = 0;
40	        while(filename[filename_pos] != '/' && filename[filename_pos] != '\0'){
41	            nextdirname[nextdirname_pos++] = filename[filename_pos++];
42	        }
43	        nextdirname[nextdirname_pos] = '\0';
44	
45	        // Last?
46	        if(filename[filename_pos] == '\0'){
47	            break;
48	        }
49	
50	        // Search
51	        int i = 0;
52	        uint16_t nextdir_inode_id;
53	        uint32_t nextdir_block_id;
54	        for(i = 0; i < 128; i++){
55	            if(cur_dir->entry[i].type == DIR && !strcmp(cur_dir->entry[i].name, nextdirname)){
56	                nextdir_inode_id = cur_dir->entry[i].inode;
57	                inode_t* nextdir_inode = read_inode(nextdir_inode_id);
58	                nextdir_block_id = nextdir_inode->direct_blocks[0];
59	                lastdir_inode = nextdir_inode_id;
60	                lastdir_block = nextdir_block_id;
61	                break;
62	            }
63	        }
64	        if(i == 128){
65	            disable_sum();
66	            return 0;
67	        }
68	
69	        filename_pos++;
70	        read_block(nextdir_block_id);
71	        cur_dir = cached_block_base;
72	    }
73	
74	    disable_sum();
75	    /* Search Parent Dir End */
76	
77	    read_block(lastdir_block);
78	    cur_dir = cached_block_base;
79	    for(int i = 0; i < 128; i++){
80	        if(cur_dir->entry[i].type == FILE && !strcmp(cur_dir->entry[i].name, nextdirname)){
81	            return 0;
82	        }
83	    }
84	    
85	    for(int i = 0; i < 128; i++){
86	        if(cur_dir->entry[i].type == EMPTY){
87	            uint16_t inode_id = alloc_inode();
88	
89	            // Modify Current Dir
90	            cur_dir->entry[i].type = FILE;
91	            strcpy(cur_dir->entry[i].name, nextdirname);
92	            cur_dir->entry[i].inode = inode_id;
93	            write_block(lastdir_block);
94	
95	            // Modify New Inode
96	            inode_t* new_inode = read_inode(inode_id);
97	            new_inode->mode = 0;
98	            new_inode->owner = current_running[cpu_id]->pid;
99	            new_inode->size = 0;
100	            new_inode->link = 1;
101	            write_inode(inode_id);
102	
103	            return 1;
104	        }
105	    }
106	    return 0;
107	}
