292	int do_fread(int fd, char* buffer, int size)
293	{
294	    if(fd_list[fd].access == O_WRONLY){
295	        return 0;
296	    }
297	
298	    inode_t* inode = read_inode(fd_list[fd].inode);
299	    if(fd_list[fd].rd_pos + size > inode->size){
300	        return 0;
301	    }
302	     
303	    int copied_byte = 0;
304	    while(copied_byte < size){
305	        int block_num = fd_list[fd].rd_pos / 4096;
306	        int block_id;
307	        if(block_num < 10){
308	            block_id = inode->direct_blocks[block_num];
309	        }
310	        else if(block_num >= 10 && block_num < 10 + 1024){
311	            block_id = inode->indirect_blocks[0];
312	            read_block(block_id);
313	            uint32_t* pointer = cached_block_base;
314	            block_id = *(pointer + block_num - 10);
315	        }
316	        else if(block_num >= 10 + 1024 && block_num < 10 + 1024 + 1024){
317	            block_id = inode->indirect_blocks[1];
318	            read_block(block_id);
319	            uint32_t* pointer = cached_block_base;
320	            block_id = *(pointer + block_num - 10 - 1024);
321	        }
322	        read_block(block_id);
323	
324	        int offset = fd_list[fd].rd_pos % 4096;
325	        int copy_byte;
326	        if(size - copied_byte <= 4096 - offset){
327	            copy_byte = size - copied_byte;
328	        }
329	        else{
330	            copy_byte = 4096 - offset;
331	        }
332	
333	        enable_sum();
334	        memcpy(buffer + copied_byte, ((uint8_t*)cached_block_base) + offset, copy_byte);
335	        disable_sum();
336	
337	        copied_byte += copy_byte;
338	        fd_list[fd].rd_pos += copy_byte;
339	    }
340	
341	    return size;
342	}
