344	int do_fwrite(int fd, char* buffer, int size)
345	{
346	    if(fd_list[fd].access == O_RDONLY){
347	        return 0;
348	    }
349	
350	    inode_t* inode = read_inode(fd_list[fd].inode);
351	
352	    int cur_block = (inode->size == 0) ? 0 : (inode->size / 4096 + 1);
353	    inode->size = inode->size + size;
354	    int total_block = (inode->size == 0) ? 0 : (inode->size / 4096 + 1);
355	    int needed_block = total_block - cur_block;
356	
357	    if(total_block >= 10 && cur_block < 10){
358	        inode->indirect_blocks[0] = alloc_block();
359	    }
360	    if(total_block >= 10 + 1024 && cur_block < 10 + 1024){
361	        inode->indirect_blocks[1] = alloc_block();
362	    }
363	
364	    for(int i = 0; i < needed_block; i++){
365	        int block_num = cur_block + i;
366	        if(block_num < 10){
367	            inode->direct_blocks[block_num] = alloc_block();
368	        }
369	        else if(block_num >= 10 && block_num < 10 + 1024){
370	            int block_id = inode->indirect_blocks[0];
371	            read_block(block_id);
372	            uint32_t* pointer = cached_block_base;
373	            *(pointer + block_num - 10) = alloc_block();
374	            write_block(block_id);
375	        }
376	        else if(block_num >= 10 + 1024 && block_num < 10 + 1024 + 1024){
377	            int block_id = inode->indirect_blocks[1];
378	            read_block(block_id);
379	            uint32_t* pointer = cached_block_base;
380	            *(pointer + block_num - 10 - 1024) = alloc_block();
381	            write_block(block_id);
382	        }
383	    }
384	    
385	    write_inode(fd_list[fd].inode);
386	
387	    int copied_byte = 0;
388	    while(copied_byte < size){
389	        int block_num = fd_list[fd].wr_pos / 4096;
390	        int block_id; 
391	        if(block_num < 10){
392	            block_id = inode->direct_blocks[block_num];
393	        }
394	        else if(block_num >= 10 && block_num < 10 + 1024){
395	            block_id = inode->indirect_blocks[0];
396	            read_block(block_id);
397	            uint32_t *pointer = cached_block_base;
398	            block_id = *(pointer + block_num - 10);
399	        }
400	        else if(block_num >= 10 + 1024 && block_num < 10 + 1024 + 1024){
401	            block_id = inode->indirect_blocks[1];
402	            read_block(block_id);
403	            uint32_t *pointer = cached_block_base;
404	            block_id = *(pointer + block_num - 10 - 1024);
405	        }
406	
407	        read_block(block_id);
408	
409	        int offset = fd_list[fd].wr_pos % 4096;
410	        int copy_byte;
411	        if(size - copied_byte <= 4096 - offset){
412	            copy_byte = size - copied_byte;
413	        }
414	        else{
415	            copy_byte = 4096 - offset;
416	        }
417	
418	        enable_sum();
419	        memcpy(((uint8_t*)cached_block_base) + offset, buffer + copied_byte, copy_byte);
420	        write_block(block_id);
421	        disable_sum();
422	
423	        copied_byte += copy_byte;
424	        fd_list[fd].wr_pos += copy_byte;
425	    }
426	
427	    return size;
428	}
