        int i = 0;
        uint16_t nextdir_inode_id;
        uint32_t nextdir_block_id;
        for(i = 0; i < 128; i++){
            if(cur_dir->entry[i].type == DIR && !strcmp(cur_dir->entry[i].name, nextdirname)){
                nextdir_inode_id = cur_dir->entry[i].inode;
